const r = $input.first().json;
const soll = {
  kunde:             { wert: "Miriam Koch",    aufgabe: 1 },
  stadt:             { wert: "Mannheim",       aufgabe: 1 },
  erster_artikel:    { wert: "Laptop-Ständer", aufgabe: 2 },
  anzahl_positionen: { wert: 3,                aufgabe: 2, typ: "number" },
  status_text:       { wert: "offen",          aufgabe: 3 },
  bestellnummer:     { wert: "A-1042",         aufgabe: 4 },
  grosse_bestellung: { wert: true,             aufgabe: 5, typ: "boolean" }
};
const typName = { number: "Number", boolean: "Boolean" };
const hinweise = [];
for (const [feld, s] of Object.entries(soll)) {
  const v = r[feld];
  if (v === undefined || v === null || v === "") {
    const aehnlich = Object.keys(r).find(k => k.toLowerCase() === feld.toLowerCase());
    hinweise.push(aehnlich
      ? `Aufgabe ${s.aufgabe}: Feld '${feld}' fehlt, es gibt aber '${aehnlich}'. Groß-/Kleinschreibung zählt!`
      : `Aufgabe ${s.aufgabe}: Feld '${feld}' fehlt oder ist leer. Stimmt der Pfad in der Expression?`);
  } else if (String(v) !== String(s.wert)) {
    hinweise.push(`Aufgabe ${s.aufgabe}: Feld '${feld}' ist '${v}', erwartet wird '${s.wert}'.`);
  } else if (s.typ && typeof v !== s.typ) {
    hinweise.push(`Aufgabe ${s.aufgabe}: Wert von '${feld}' stimmt, ist aber Text. Typ im Set-Node auf ${typName[s.typ]} stellen.`);
  }
}
return [{
  json: {
    timestamp: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    korrekt:   hinweise.length === 0 ? "✅ Ja" : "❌ Nein",
    hinweise:  hinweise.length ? hinweise.join(" | ") : "Alles richtig. Weiter mit Modul 1!",
    kunde: r.kunde, stadt: r.stadt, erster_artikel: r.erster_artikel,
    anzahl_positionen: r.anzahl_positionen, status_text: r.status_text,
    bestellnummer: r.bestellnummer, grosse_bestellung: r.grosse_bestellung
  }
}];
